function incomeUseR49(int $year,string $code,string $mode='normal',bool $whole=false):array {
 $contract=INCOME_USE_R49[$code]??null;if(!$contract||!in_array($year,[2025,2026],true)||!in_array($mode,['normal','cancelled','tax'],true))throw new DomainException('Exact original result-use fixture required.');
 $counter=$contract['fixture_counter_code'];$counterGroup=$contract['fixture_counter_group'];
 $chart=C::chart(['bank'=>['name'=>'Synthetic bank','group'=>'cash','skr_code'=>'18000'],'capital'=>['name'=>'Synthetic original capital','group'=>'equity','skr_code'=>'25000'],'use'=>['name'=>'Synthetic original result-use decision','group'=>'result_use','skr_code'=>$code],'income'=>['name'=>'Synthetic original earned income','group'=>'revenue','skr_code'=>'40000']]+($counter==='bank'?[]:['counter'=>['name'=>'Synthetic original capital or reserve counterpart','group'=>$counterGroup,'skr_code'=>$counter]]));
 $line=static fn($a,$d,$c,$s='')=>['account'=>$a,'debit_cents'=>$d,'credit_cents'=>$c,'sphere'=>$s];
 $n=1234;$loss=$code==='77200';$release=$contract['release'];$opening=[$line('bank',1000000,0),$line('capital',0,1000000)];
 if($counter!=='bank'&&($release||$loss)){$initial=in_array($code,['77000','77200'],true)?$n:100000;$opening[]=$line('counter',$loss?$initial:0,$loss?0:$initial);if($loss)$opening[1]['credit_cents']+=$initial;else $opening[0]['debit_cents']+=$initial;}
 $entries=[['id'=>hash('md5','synthetic-earned-income-'.$year),'date'=>$year.'-05-01','description'=>'Original synthetic earned annual income','lines'=>[$line('bank',40000,0),$line('income',0,40000,'4')]]];
 $useCredit=$release&&!$loss;$key=$counter==='bank'?'bank':'counter';$use=['id'=>hash('md5','synthetic-original-result-use-'.$year.'-'.$code),'date'=>$year.'-10-01','description'=>'Synthetic original reviewed result-use resolution','lines'=>[$line('use',$useCredit?0:$n,$useCredit?$n:0),$line($key,$useCredit?$n:0,$useCredit?0:$n)]];$entries[]=$use;
 if($mode==='cancelled'){$rev=$use;$rev['id']=hash('md5',$use['id'].'-cancelled');$rev['date']=$year.'-11-01';$rev['reversal_of']=$use['id'];foreach($rev['lines'] as &$l){$tmp=$l['debit_cents'];$l['debit_cents']=$l['credit_cents'];$l['credit_cents']=$tmp;}unset($l);$entries[]=$rev;}
 $cal=C::build($year,$chart,$opening,$entries);if($cal['issues'])throw new DomainException(implode(' ',$cal['issues']));$source=['year'=>$year,'state'=>'closed','closed_sha256'=>hash('sha256',json_encode([$year,$chart,$opening,$entries],JSON_THROW_ON_ERROR)),'previous_sha256'=>null,'result_account'=>'capital','issues'=>[],'accounts'=>$chart,'opening'=>$opening,'entries'=>$entries,'calculation'=>$cal,'asset_schedule'=>['year'=>$year,'items'=>[],'totals'=>array_fill_keys(['cost_opening_cents','additions_cents','cost_closing_cents','accumulated_opening_cents','depreciation_cents','accumulated_closing_cents','book_opening_cents','book_closing_cents'],0),'issues'=>[]]];
 $review=['year'=>$year,'journal_sha256'=>$source['closed_sha256'],'complete'=>true,'opening_adjustments'=>[],'current_adjustments'=>[]];
 if($mode==='tax'){if($code!=='77490')throw new DomainException('Explicit source tax fixture required.');$review['current_adjustments']=[['id'=>'source-tax-use','reason'=>'Synthetic independently reviewed tax capital transfer','lines'=>$use['lines']]];}
 if($whole){$decisions=[];foreach($entries as $e)foreach($e['lines'] as $i=>$l){if(!in_array($chart[$l['account']]['group'],['equity','reserves','result_use'],true))continue;$type=$counter==='bank'?($l['debit_cents']?'withdrawal':'contribution'):'reclassification';$decisions['journal:'.$e['id'].':'.$i]=['kind'=>$type,'reason'=>'Synthetic original approved distribution or internal capital reclassification'];}foreach($review['current_adjustments'] as $e)foreach($e['lines'] as $i=>$l)$decisions['tax:'.$e['id'].':'.$i]=['kind'=>'reclassification','reason'=>'Synthetic independently reviewed tax reserve transfer'];$review['capital_movements']=$decisions;}
 return T::build($whole?W::fromReport($source):$source,$review);
}
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){set_error_handler(static function($s,$m,$f,$l){throw new ErrorException($m,0,$s,$f,$l);});echo json_encode(incomeUseR49((int)$argv[1],$argv[2],$argv[3]??'normal',($argv[4]??'')==='whole'),JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
